/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

import type { NextConfig } from 'next';
import { vercelAnalyticsCspSources } from './src/lib/analytics-config';

function configuredHttpsUrl(value: string | undefined): URL | null {
  const candidate = value?.trim();
  if (!candidate) return null;
  try {
    const url = new URL(candidate);
    if (url.protocol !== 'https:' || url.username || url.password) return null;
    return url;
  } catch {
    return null;
  }
}

const contentBlobBaseUrl = configuredHttpsUrl(process.env.CONTENT_BLOB_BASE_URL);
const publicMediaUrl = configuredHttpsUrl(process.env.CLOUDFLARE_R2_PUBLIC_URL);
const configuredMediaUrls = [contentBlobBaseUrl, publicMediaUrl]
  .filter((url): url is URL => url !== null);
const configuredMediaOrigins = [...new Set(configuredMediaUrls.map((url) => url.origin))];
const mediaSourceList = configuredMediaOrigins.length > 0
  ? ` ${configuredMediaOrigins.join(' ')}`
  : '';
const analyticsCsp = vercelAnalyticsCspSources();
const analyticsScriptSourceList = analyticsCsp.script.length > 0
  ? ` ${analyticsCsp.script.join(' ')}`
  : '';
const analyticsConnectSourceList = analyticsCsp.connect.length > 0
  ? ` ${analyticsCsp.connect.join(' ')}`
  : '';

const nextConfig: NextConfig = {
  distDir: process.env.NEXT_DIST_DIR?.trim() || '.next',
  poweredByHeader: false,
  compress: true,
  serverExternalPackages: ['@prisma/client', '.prisma/client'],
  outputFileTracingExcludes: {
    '*': ['public/figures/**', 'public/medical-diagrams/**', 'public/downloads/**', 'open-content/medical-figures/images/**', 'public/icons/**', 'public/screenshots/**'],
  },
  experimental: {
    optimizePackageImports: ['next-auth', 'katex', '@anthropic-ai/sdk', 'openai', 'zod'],
    staleTimes: { dynamic: 30, static: 180 },
  },
  images: {
    remotePatterns: configuredMediaUrls.map((url) => ({
      protocol: 'https' as const,
      hostname: url.hostname,
      port: url.port,
      pathname: '/**',
    })),
    formats: ['image/avif', 'image/webp'],
  },
  async headers() {
    const scriptDevAllowance = process.env.NODE_ENV === 'development'
      ? " 'unsafe-eval'"
      : '';
    const cspReportOnly = [
      `default-src 'self'`,
      `script-src 'self' 'unsafe-inline'${scriptDevAllowance}${analyticsScriptSourceList}`,
      `style-src 'self' 'unsafe-inline'`,
      `img-src 'self' data: blob:${mediaSourceList}`,
      `media-src 'self'${mediaSourceList}`,
      `font-src 'self' data:`,
      `connect-src 'self'${analyticsConnectSourceList}${mediaSourceList}`,
      `frame-ancestors 'none'`,
      `object-src 'none'`,
      `base-uri 'self'`,
      `form-action 'self'`,
      `report-uri /api/security/csp-report`,
    ].join('; ');
    const securityHeaders = [
      { key: 'X-Content-Type-Options', value: 'nosniff' },
      { key: 'X-Frame-Options', value: 'DENY' },
      { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
      { key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains; preload' },
      { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
      { key: 'Content-Security-Policy-Report-Only', value: cspReportOnly },
    ];
    return [
      { source: '/(.*)', headers: securityHeaders },
    ];
  },
};

export default nextConfig;

import 'dotenv/config';
import path from 'node:path';
import { defineConfig } from 'prisma/config';

// Generation and offline builds need a syntactically valid URL but never connect.
// Port 1 makes accidental database commands fail closed unless DATABASE_URL is set.
const databaseUrl = process.env.DATABASE_URL
  ?? 'postgresql://foss:foss@127.0.0.1:1/foss';

export default defineConfig({
  schema: path.join(__dirname, 'prisma', 'schema'),
  migrations: {
    path: path.join(__dirname, 'prisma', 'migrations'),
    seed: 'node --import tsx scripts/usmle/seed-open-corpus.ts',
  },
  datasource: {
    url: databaseUrl,
  },
  // Prisma's current config types lag the runtime support for migrate adapters.
  // @ts-expect-error runtime-supported, but missing from PrismaConfig typing
  migrate: {
    adapter: async () => {
      const pg = await import('pg');
      return new pg.default.Pool({ connectionString: databaseUrl });
    },
  },
});

generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["postgresqlExtensions"]
}

datasource db {
  provider   = "postgresql"
  extensions = [pgvector(map: "vector")]
}

// NextAuth.js required models
model Account {
  id                String  @id @default(cuid())
  userId            String
  type              String
  provider          String
  providerAccountId String
  refresh_token     String? @db.Text
  access_token      String? @db.Text
  expires_at        Int?
  token_type        String?
  scope             String?
  id_token          String? @db.Text
  session_state     String?
  user              User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([provider, providerAccountId])
  @@index([userId])
}

model Session {
  id           String   @id @default(cuid())
  sessionToken String   @unique
  userId       String
  expires      DateTime @db.Timestamptz(3)
  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
}

model User {
  id            String    @id @default(cuid())
  name          String?
  email         String?   @unique
  emailVerified DateTime? @db.Timestamptz(3)
  image         String?

  // Email aliases (for login with multiple emails)
  emailAliases UserEmail[]

  // Profile
  cohort        Int? // Graduation year cohort
  medSchool     String? // University
  studyGoal     Int? // Daily card target
  track         Int? // Optional institution-defined stream number
  // Set when someone whose course md3 does not cover describes it in their own
  // words (the rotation chooser's "something else"). It stops the chooser
  // re-asking a question they have already answered, and marks them as waiting
  // on a human decision — their request is in the UserFeedback queue that the
  // morning check works. Nulled by hand if they should be asked afresh.
  curriculumRequestedAt DateTime? @db.Timestamptz(3)
  // Opt-in leaderboard: joined means visible to other joined learners under
  // the handle they chose; both null until the learner joins.
  leaderboardHandle   String?   @unique
  leaderboardJoinedAt DateTime? @db.Timestamptz(3)
  ccSubrotation String? // Current CC sub-rotation: 'icu' | 'anaesthetics' | 'em'

  // Institution
  institution    String? // 'usyd' | 'usmle' | 'other'
  enabledModules String[] @default(["ecg", "cxr", "abg"]) // Universal modules enabled for mixing

  // Active modules - hierarchical module tree selection
  // Slugs like "cc/icu", "gsse/anatomy" - see ModuleNode
  activeModules String[] @default([])

  // Review focus menu. Until reviewMenuCustomized is set, the shared default
  // applies (current block + the main subject decks). Afterwards
  // reviewMenuModules replaces that default.
  reviewMenuCustomized Boolean  @default(false)
  reviewMenuModules    String[] @default([])

  // Jurisdiction - determines which guidelines/protocols to show
  // 'nsw' | 'wa' | 'national' | null (null = show all/infer from institution)
  jurisdiction String?

  // Feature access
  betaAccess Boolean @default(false) // Enables video/reels section
  imageTier  String  @default("standard") // 'standard' | 'copyright' — gates copyright-required images

  // Feed profile — accumulated from inline polls and profiling cards
  // Structure: { explicit: {studying, year, school}, implicit: {pollAnswers, ...}, feedBias: {} }
  feedProfile Json?

  // Preferences
  darkMode            Boolean @default(false)
  emailDigest         Boolean @default(true) // Weekly progress emails
  preferAbbreviations Boolean @default(false) // Display "MI" vs "myocardial infarction"

  // Stats (denormalized for quick access)
  totalStudyTime Int       @default(0) // Minutes
  currentStreak  Int       @default(0) // Days
  longestStreak  Int       @default(0)
  lastActiveAt   DateTime? @db.Timestamptz(3)

  // Durable privacy-deletion tombstone. UserDocument presign creation locks
  // this row and fails closed once requestedAt is set. notBefore is the latest
  // issued PUT expiry plus a safety margin; account cleanup cannot finalise
  // before it.
  privacyDeletionRequestedAt DateTime? @db.Timestamptz(3)
  privacyDeletionNotBefore   DateTime? @db.Timestamptz(3)

  createdAt DateTime @default(now()) @db.Timestamptz(3)

  // Relations
  accounts                   Account[]
  sessions                   Session[]
  cardProgress               CardProgress[]
  rotations                  UserRotation[]
  pageViews                  PageView[]
  questionResponses          QuestionResponse[]
  examPaperSessions ExamPaperSession[]
  anonymousSessions          AnonymousSession[]
  termStates                 UserTermState[]
  deepDiveChatSessions       DeepDiveChatSession[]
  clusterStates              UserClusterState[]
  ContentExposure            ContentExposure[]
  videoProgress              VideoProgress[]
  documents                  UserDocument[]
  serveDecisions             ServeDecision[]
  schedulerDecisionSets      SchedulerDecisionSet[]
  examTargetDecisionAttempts ExamTargetDecisionAttempt[]
  syncOperations             SyncOperation[]
  examResults                ExamResult[]
  ownedCards                 Card[]                      @relation("OwnedCards")
  ankiCollections            AnkiCollection[]
  ankiObjects                AnkiObject[]
  ankiCustodyReviews         AnkiCustodyReview[]
  ankiMedia                  AnkiMedia[]
  studyDecks                 StudyDeck[]
  studyNoteTypes             StudyNoteType[]
  studyNotes                 StudyNote[]
  importEpochs               ImportEpoch[]
  ankiBridgePairings         AnkiBridgePairing[]
  ankiSyncPeers              AnkiSyncPeer[]
  ankiExportJobs             AnkiExportJob[]
  ankiImportJobs             AnkiImportJob[]
}

// User-uploaded documents (PDFs, zips, etc.) — targeting system for profile
model UserDocument {
  id     String @id @default(cuid())
  userId String
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)

  filename  String // Original filename
  r2Key     String // R2 object key
  mimeType  String // MIME type
  sizeBytes Int // File size in bytes
  status    String @default("pending") // pending | quarantined | pending-deletion | error; legacy ready rows may exist but no automatic processing path

  // Every direct-upload URL is valid for a bounded window. Deletion first
  // persists a tombstone and waits through that window so a stale PUT cannot
  // recreate an object after R2 cleanup.
  uploadUrlExpiresAt  DateTime  @default(dbgenerated("(CURRENT_TIMESTAMP + '00:10:00'::interval)")) @db.Timestamptz(3)
  deletionRequestedAt DateTime? @db.Timestamptz(3)
  deleteAfter         DateTime? @db.Timestamptz(3)

  metadata Json? // Future: extracted topics, concepts, etc.

  createdAt DateTime @default(now()) @db.Timestamptz(3)
  updatedAt DateTime @updatedAt @db.Timestamptz(3)

  @@index([userId])
  @@index([status, deleteAfter])
}

// Email aliases - allows users to log in with multiple email addresses
// All aliases point to the same User account
model UserEmail {
  id     String @id @default(cuid())
  email  String @unique // The alias email address (case-insensitive lookup)
  userId String
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)

  // Verification
  verified   Boolean   @default(false)
  verifiedAt DateTime? @db.Timestamptz(3)

  // Metadata
  createdAt DateTime @default(now()) @db.Timestamptz(3)
  label     String? // Optional label like "Work", "Personal", "University"

  @@index([userId])
}

// Track anonymous users before they log in
model AnonymousSession {
  id String @id @default(cuid())

  // Browser fingerprint (privacy-respecting hash)
  fingerprint String // hash of: userAgent + screenSize + timezone

  // Optional link to user (if they log in later)
  userId String?
  user   User?   @relation(fields: [userId], references: [id])

  // Session timestamps
  startedAt    DateTime @default(now()) @db.Timestamptz(3)
  lastActiveAt DateTime @default(now()) @db.Timestamptz(3)

  // Aggregated activity (for login nudge thresholds)
  cardsViewed   Int @default(0)
  mcqsAttempted Int @default(0)
  pagesRead     Int @default(0)

  // Progressive profile — accumulated from feed interactions
  profile Json? // { explicit: {studying, year, school}, implicit: {topTopics, avgDwellMs, ...}, feedBias: {} }

  feedEvents FeedEvent[]

  @@index([fingerprint])
  @@index([userId])
}

// Append-only event log for anonymous feed interactions
model FeedEvent {
  id                 String   @id @default(cuid())
  sessionFingerprint String? // Nullable since 2026-05-09 — authenticated users can record events directly via userId without an AnonymousSession.
  userId             String? // Populated on signup via linkSessionToUser
  eventType          String // impression, interact, scroll, profile_answer, signup_click
  itemId             String? // Content item ID or inline card slug
  itemType           String? // video, mcq, cloze, teach, poll, profiling, cta
  feedPosition       Int? // Position in the feed (0-indexed)
  action             String? // play, pause, complete, answer, reveal, vote_up, vote_down, bookmark
  result             String? // correct/incorrect, poll answer text, profiling answer
  dwellMs            Int? // Time spent on this item
  metadata           Json? // Overflow bag (video watch %, scroll depth, etc.)
  timestamp          DateTime @default(now()) @db.Timestamptz(3)

  session AnonymousSession? @relation(fields: [sessionFingerprint], references: [id])

  @@index([sessionFingerprint, timestamp])
  @@index([itemId, eventType])
  @@index([userId, timestamp])
  @@index([eventType, timestamp])
}

// Atomic cross-instance request-throttling bucket. Keys are SHA-256 hashes of
// their route/user-or-IP namespace, so the table never stores raw identifiers.
model RateLimitBucket {
  key             String   @id @db.VarChar(71)
  count           Int
  windowStartedAt DateTime @db.Timestamptz(3)
  expiresAt       DateTime @db.Timestamptz(3)
  updatedAt       DateTime @updatedAt @db.Timestamptz(3)

  @@index([expiresAt])
}

// Track agent work for content improvement
model AgentJob {
  id String @id @default(cuid())

  // Job classification
  type     String // 'create_mcq_variant', 'fix_flagged_card', etc.
  priority Int    @default(2) // 1=urgent, 2=normal, 3=low

  // What it relates to
  rotation   String?
  conceptId  String?
  cardId     String?
  questionId String?

  // Why it was created
  trigger  String // 'repetition_detected', 'flag_threshold', etc.
  metadata Json? // Context for the agent

  // Workflow state
  status      String    @default("pending") // pending, claimed, completed, dismissed
  claimedBy   String? // Agent session identifier
  claimedAt   DateTime? @db.Timestamptz(3)
  completedAt DateTime? @db.Timestamptz(3)
  result      Json? // What the agent produced

  createdAt DateTime @default(now()) @db.Timestamptz(3)

  @@index([status, priority])
  @@index([type])
  @@index([rotation])
}

model VerificationToken {
  identifier String
  token      String   @unique
  expires    DateTime @db.Timestamptz(3)

  @@unique([identifier, token])
}

// =============================================================================
// CONTENT MODELS
// Card, Question, QuestionConcept, QuestionGroup, ContentVersion,
// ModuleNode, Cluster, UserClusterState, ContentGap
// =============================================================================

// =============================================================================
// MODULE TREE - Hierarchical module selection system
// See docs/plans/2026-01-25-module-selection-ux.md
// =============================================================================

// ModuleNode - Represents a node in the module tree
// Users activate nodes at any level: "cc" (all CC), "cc/icu" (just ICU), etc.
model ModuleNode {
  id   String @id @default(cuid())
  slug String @unique // "cc", "cc/icu", "gsse", "gsse/anatomy"
  name String // "ICU", "Anatomy"

  // Tree structure
  parentSlug String? // Parent node slug (null for root nodes)

  // Classification
  nodeType String // "institution" | "module" | "rotation" | "subrotation" | "trainer" | "section"

  // Display
  description String?
  icon        String? // Emoji or icon name
  color       String? // Hex color for UI theming
  sortOrder   Int     @default(0)

  // Visibility
  isPublished Boolean @default(true)

  createdAt DateTime @default(now()) @db.Timestamptz(3)
  updatedAt DateTime @updatedAt @db.Timestamptz(3)

  @@index([parentSlug])
  @@index([nodeType])
}

// Concept clusters (auto-generated from embeddings)
model Cluster {
  id         String             @id @default(cuid())
  name       String // Auto-labeled from common topics
  rotations  String[] // Which rotations this cluster spans
  cardCount  Int                @default(0)
  videoCount Int                @default(0)
  cards      Card[]
  videos     Video[]
  userStates UserClusterState[]
  createdAt  DateTime           @default(now()) @db.Timestamptz(3)
  updatedAt  DateTime           @updatedAt @db.Timestamptz(3)
}

// UserClusterState - Persisted mastery state per user per cluster
// Aggregates CardProgress within each cluster for fast reads
model UserClusterState {
  id        String @id @default(cuid())
  userId    String
  clusterId String

  // Mastery metrics (aggregated from CardProgress)
  mastery       Float @default(0) // 0-1, combined strength * coverage
  avgRetrieval  Float @default(0) // Average retrievalStrength of reviewed cards
  coverage      Float @default(0) // Fraction of cluster cards reviewed
  cardsReviewed Int   @default(0)
  cardsTotal    Int   @default(0)

  // Tracking
  needsAttention Boolean   @default(false) // Low mastery, significant cluster
  lastReviewedAt DateTime? @db.Timestamptz(3) // Last time user reviewed a card in this cluster
  lastComputedAt DateTime  @default(now()) @db.Timestamptz(3)

  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)
  cluster Cluster @relation(fields: [clusterId], references: [id], onDelete: Cascade)

  @@unique([userId, clusterId])
  @@index([userId, needsAttention])
  @@index([clusterId])
}

// IMPORTANT: All content verticals share Card/Question.
// Use the `rotation` field to distinguish content (e.g. "gsse", "anatomy", "usmle-step1").
// Do NOT create vertical-specific card/question/progress models.
// Cards (auto-generated from MDX content)
model Card {
  id       String @id @default(cuid())
  cardType String // 'cloze' | 'mcq' | 'pathway' | 'comparison' | 'decision' | 'timeline'
  rotation String // Primary routing slug (page/URL/scheduler partition). 'critical-care' | 'cah' | 'paam' | 'pwh' | 'year1-kat1' | 'usmle' | …. See docs/designs/2026-05-09-rotation-vs-modulenodes.md
  week     Int? // 1-7 for week-based content; 0/null for generic or non-week content

  // Module tree - which modules this card belongs to
  // e.g., ["cc", "cc/icu", "gsse/anatomy"] - shows if user has any of these active
  moduleNodes     String[]     @default([])
  sourceFile      String? // 'week1-resuscitation'
  sourceComponent String // 'Mnemonic' | 'KeyPoint' | 'MCQ' | 'Danger' | 'ClinicalPearl'
  // Deterministic identifier for MDX-seeded cards (content hash).
  // Used to upsert on seed so user progress isn't wiped on reseed.
  stableId        String?      @unique
  // Private/user-authored cards remain in the shared study-item table, but are
  // visible only through an explicit owner/deck/active-epoch access scope.
  ownerUserId     String?
  ownerUser       User?        @relation("OwnedCards", fields: [ownerUserId], references: [id], onDelete: Cascade, onUpdate: Restrict)
  studyDeckId     String?
  studyDeck       StudyDeck?   @relation(fields: [studyDeckId, ownerUserId], references: [id, ownerUserId], onDelete: Cascade, onUpdate: Restrict)
  studyNoteId     String?
  studyNote       StudyNote?   @relation(fields: [studyNoteId, ownerUserId], references: [id, ownerUserId], onDelete: Cascade, onUpdate: Restrict)
  importEpochId   String?
  importEpoch     ImportEpoch? @relation(fields: [importEpochId, studyDeckId], references: [id, studyDeckId], onDelete: Cascade, onUpdate: Restrict)
  templateOrdinal Int?
  portableCardId  String?      @unique
  front           String       @db.Text // Question with [___] blanks
  back            String       @db.Text // Answer (single answer for simple cloze)
  backs           Json? // Array of answers for multi-cloze one-by-one cards
  context         String?      @db.Text // Teaching context shown after answer reveal
  topics          String[]
  difficulty      String       @default("medium") // 'easy' | 'medium' | 'hard'
  importance      Int          @default(1) // 1-3, higher = more exam-relevant
  complexity      Int          @default(2) // 1=trivial, 2=moderate, 3=complex (for mastery/retirement)

  // Cloze variant grouping (2026-05-08)
  // Multi-blank MDX entries split into N single-blank sibling cards at seed time;
  // siblings share variantGroupId. See docs/superpowers/specs/2026-05-08-cloze-variants-design.md
  variantGroupId String?
  variantIndex   Int?
  variantType    String? // 'cloze-blank' | 'legacy-anchor'

  // Jurisdiction - which health system's guidelines this follows
  // null = universal (anatomy, physiology, etc.)
  // 'nsw' | 'wa' | 'national' = jurisdiction-specific protocols
  jurisdiction String?

  // Practice locale — coarse AU vs US twin axis (discrepancy-triggered).
  // null = universal (no split). Distinct from protocol `jurisdiction`.
  // See docs/superpowers/specs/2026-08-10-au-us-practice-locale-twins-design.md
  practiceLocale String? // 'au' | 'us' | null

  // Jurisdiction variants - cards with same conceptId are the same concept
  // but authored for different jurisdictions (e.g., NSW vs WA protocols)
  // Details page shows all variants for comparison
  conceptId String?

  // Visual card system (2026-01-17)
  visualData    Json? // Structured data for visual rendering (nodes, branches, rows, etc.)
  annotations   Json? // {"HR 142": "↑ tachycardia", "Lactate 5.1": "↑↑ severe, nl <2"}
  abbreviations Json? // {"RSI": "Rapid Sequence Intubation", "VF": "Ventricular Fibrillation"}
  crosslinks    Json? // {primary: "/critical-care/week1", concepts: ["shock", "RSI"]}
  imageUrl      String? // Path to associated image (e.g., "/figures/ecg/vf-real.jpg")
  // Caption that names the finding and tells the student where to look.
  // Required whenever imageUrl is set (enforced by detector, not yet schema)
  // — without it, the image renders as decoration. See pedagogy_harness memory.
  imageCaption  String? @db.Text
  imageRole     String? // 'prompt' = image is the card stem (image-as-prompt, copyright-tier only); null = decoration

  // Operative video clip system. The clip is the card's STEM the way an
  // image-as-prompt image is. Mechanism only: the table ships empty, and
  // delivery fails closed on VideoSource.rightsStatus, so a deployment that
  // holds no cleared source serves no clip.
  clipId      String?
  clip        VideoClip? @relation(fields: [clipId], references: [id], onDelete: SetNull, onUpdate: Restrict)
  clipRole    String? // 'prompt' = the clip IS the stem; null = after-reveal demonstration
  clipCaption String?    @db.Text

  feedScore Int @default(0) // 0-10: how engaging for anonymous cold audience

  // Cluster assignment
  clusterId String?
  cluster   Cluster? @relation(fields: [clusterId], references: [id])

  // Cached similar cards (top 10, computed offline)
  similarCards Json? // [{cardId: string, similarity: number}]

  factId String?
  fact   Fact?   @relation(fields: [factId], references: [id])

  // Quality record — structured pedagogical metadata
  // See docs/designs/2026-02-01-study-item-quality-model.md
  // Uses ItemQualityRecord interface from src/lib/quality/types.ts
  quality Json? @db.JsonB

  // Pedagogy — clinical reasoning, misconceptions, source justification
  // Uses CardPedagogy interface from src/lib/pedagogy/card-pedagogy.ts
  pedagogy Json? @db.JsonB

  createdAt DateTime  @default(now()) @db.Timestamptz(3)
  deletedAt DateTime? @db.Timestamptz(3) // Soft-delete: set when card removed from MDX, preserves CardProgress history
  shelvedAt DateTime? @db.Timestamptz(3) // Parked: card needs work (e.g. missing image) but shouldn't be deleted

  // Empirical difficulty signals — populated nightly by /api/cron/empirical-aggregation.
  // facilityIndex 0..1: fraction of grades with quality >= 3 across all users
  //   (mirrors Question.facilityIndex). Populated from 2 unique users; downstream
  //   complexity changes remain gated at sampleSize ≥ 10 plus uncertainty/age checks.
  // avgResponseTimeMs: median across all CardProgress for this card.
  //   Long times = high cognitive load; short times = trivial or guessable.
  // sampleSize: count of unique-user reviews contributing to the metrics.
  facilityIndex     Float?
  avgResponseTimeMs Int?
  sampleSize        Int?

  // Owner-scoped exact custody links for imported Anki cards and reviews.
  ankiObjects        AnkiObject[]        @relation("AnkiObjectMappedCard")
  ankiCustodyReviews AnkiCustodyReview[] @relation("AnkiCustodyReviewMappedCard")

  // Exam-targeting signal — populated by the exam-relevance backfill/cron.
  // examRelevance is the persisted scalar used for curation/sorting; meta keeps
  // the source breakdown and top calibration domains so the number is auditable.
  examRelevance          Float?
  examRelevanceMeta      Json?     @db.JsonB
  examRelevanceUpdatedAt DateTime? @db.Timestamptz(3)
  // Per-domain exam model (exam-target engine, 2026-06-19). examDomain is the
  // assigned official blueprint specialty area; examDomainSim its cosine to that
  // area's centroid; examRelevancePct the within-rotation percentile of domain
  // similarity (the DISCRIMINATING signal — a real low tail, unlike examRelevance).
  examDomain             String?
  examDomainSim          Float?
  examRelevancePct       Float?

  progress CardProgress[]
  question Question? // Optional link to Question if this card is a question

  // Direct citation links (hybrid model - can also link via Fact)
  cardCitations CardCitation[]

  @@unique([id, ownerUserId])
  @@index([rotation, week])
  @@index([clusterId])
  @@index([factId])
  @@index([conceptId])
  @@index([topics], type: Gin)
  @@index([deletedAt])
  @@index([feedScore])
  @@index([examRelevance])
  @@index([examRelevanceUpdatedAt])
  @@index([examDomain])
  @@index([variantGroupId])
  @@index([variantGroupId, variantIndex])
  @@index([ownerUserId, deletedAt])
  @@index([studyDeckId, importEpochId])
  @@index([studyNoteId])
  @@index([importEpochId])
  @@index([practiceLocale])
  @@index([clipId])

  // Concept links (the concept spine); see CardConcept below.
  cardConcepts CardConcept[]
}

// Note: pgvector tables (card_embeddings, question_embeddings, courseware_embeddings, concept_subspaces)
// are managed via raw SQL in scripts/setup-manifold.ts. Not in Prisma schema (@@ignore was removed
// during schema consolidation) but the DB tables persist.

// Question - Individual assessment item (KAT, textbook, AI-generated)
model Question {
  id String @id @default(cuid())

  // Content
  stem    String  @db.Text // The question scenario/prompt
  options Json // [{label: 'A', text: '...', isCorrect: boolean}]
  context String? @map("explanation") @db.Text // Teaching context: why the answer is correct

  // Organization
  rotation String // Primary routing slug (page/URL/scheduler partition). See docs/designs/2026-05-09-rotation-vs-modulenodes.md
  week     Int?
  topics   String[]

  // Module tree - hierarchical memberships for exam aggregation + multi-cohort scheduling. May span rotations.
  moduleNodes String[] @default([])

  // Metadata
  source         String // 'kat-practice', 'textbook', 'ai-generated', 'user-submitted'
  sourceFile     String? // 'CC_KAT_Practice.pdf' or source reference
  questionNumber Int? // Original question number in source

  // Question characteristics
  questionType String // 'diagnosis', 'next-step', 'mechanism', 'calculation', 'image-interpretation', 'management'
  difficulty   String @default("medium") // 'easy' | 'medium' | 'hard'

  // Cognitive format axis — orthogonal to questionType. Captures the
  // cognitive operation the student must perform: pattern recognition,
  // mechanism reasoning, scenario application, etc. Used by the scheduler
  // to prefer un-seen formats within a recently-served concept (variety
  // in *how* a concept is probed, not just *which* concept).
  // 'cloze' | 'recall' | 'mechanism' | 'interpretation' | 'trap' | 'comparison' | 'scenario' | 'unknown'
  // Backfilled by format-tagger; nullable until backfill runs.
  format String?

  // Practice locale — coarse AU vs US twin axis (see Card.practiceLocale).
  practiceLocale String? // 'au' | 'us' | null

  // Variant grouping - questions with same variantGroupId test the same concept
  // Anchor is the original; variants are shuffled/rephrased/different-scenario versions
  variantGroupId String? // UUID linking variant questions together
  variantType    String? // 'anchor' | 'shuffled' | 'rephrased' | 'different-scenario' | 'near-duplicate'

  // Analytics (computed from responses)
  discriminationIndex Float? // How well question separates strong vs weak students
  facilityIndex       Float? // % of students who get it right
  totalAttempts       Int    @default(0)

  // Option pools - for anti-pattern and deeper learning
  // combinations: [[0,1,2,3,4], [0,1,2,3,5], ...] - which options to show together
  // correctVariants: ["Paracetamol", "Acetaminophen"] - paraphrased correct answers
  combinations    Json? // Array of 5-index arrays
  correctVariants Json? // Array of strings

  // Chaining - for multi-part questions about same scenario
  chainId    String? // Groups related questions
  chainOrder Int? // Order within chain (1, 2, 3...)

  // Media
  imageUrl      String? // Path to associated image (CT, ECG, etc.)
  // Caption that names the finding and tells the student where to look.
  // Required whenever imageUrl is set (enforced by detector). See
  // pedagogy_harness memory: image without caption is decoration, not teaching.
  imageCaption  String? @db.Text
  imageRole     String? // 'prompt' = image is required to answer; null = after-reveal/optional

  // Operative video clip as the question stem. See the note on Card.
  clipId      String?
  clip        VideoClip? @relation(fields: [clipId], references: [id], onDelete: SetNull, onUpdate: Restrict)
  clipRole    String? // 'prompt' = the clip IS the stem; null = after-reveal demonstration
  clipCaption String?    @db.Text
  crosslinks    Json? // {primary: "/deep-dive/cards/<slug>", related: [], concepts: []}
  annotations   Json? // {"lactate 5.1": "↑↑ severe (normal <2)"}
  abbreviations Json? // {"STEMI": "ST-Elevation MI"}

  // Relations
  concepts          QuestionConcept[]
  responses         QuestionResponse[]
  requiredFacts     QuestionFact[] // Facts needed to answer this question
  questionCitations QuestionCitation[] // Direct MCQ → SourceCitation links (mirrors CardCitation)
  // Link to existing Card if this is an MCQ card
  cardId            String?            @unique
  card              Card?              @relation(fields: [cardId], references: [id])

  // Content pipeline state
  contentState     String    @default("raw") // raw|validated|enhanced|cited|production|escalated|shelved
  validatedAt      DateTime? @db.Timestamptz(3)
  enhancedAt       DateTime? @db.Timestamptz(3)
  citedAt          DateTime? @db.Timestamptz(3)
  promotedAt       DateTime? @db.Timestamptz(3)
  escalatedAt      DateTime? @db.Timestamptz(3)
  escalationReason String?
  citations        Json? // [{chunkId, relevanceScore, passage, connection}]

  // Pedagogical analysis ("talk page" content)
  pedagogy Json? @db.JsonB // QuestionAnalysis: primaryConcept, clinicalReasoning, misconceptions, etc.

  feedScore Int @default(0) // 0-10: how engaging for anonymous cold audience

  // Exclusion flag — replaced disk-based _exclusions/ JSON files
  excluded Boolean @default(false)

  // Exam-targeting signal — populated by the exam-relevance backfill/cron.
  // examRelevance is the persisted scalar used for curation/sorting; meta keeps
  // the source breakdown and top calibration domains so the number is auditable.
  examRelevance          Float?
  examRelevanceMeta      Json?     @db.JsonB
  examRelevanceUpdatedAt DateTime? @db.Timestamptz(3)
  // Per-domain exam model (exam-target engine, 2026-06-19) — see Card.
  examDomain             String?
  examDomainSim          Float?
  examRelevancePct       Float?

  createdAt DateTime @default(now()) @db.Timestamptz(3)
  updatedAt DateTime @updatedAt @db.Timestamptz(3)

  @@index([rotation, week])
  @@index([source])
  @@index([questionType])
  @@index([chainId])
  @@index([examDomain])
  @@index([variantGroupId])
  @@index([format])
  @@index([contentState])
  @@index([topics], type: Gin)
  @@index([feedScore])
  @@index([examRelevance])
  @@index([examRelevanceUpdatedAt])
  @@index([practiceLocale])
  @@index([clipId])
}

// QuestionConcept - Many-to-many: Question tests multiple Concepts
model QuestionConcept {
  id         String  @id @default(cuid())
  questionId String
  conceptId  String
  isPrimary  Boolean @default(false) // Is this the main concept tested?

  question Question @relation(fields: [questionId], references: [id], onDelete: Cascade)
  concept  Concept  @relation(fields: [conceptId], references: [id], onDelete: Cascade)

  @@unique([questionId, conceptId])
  @@index([conceptId])
}

// =============================================================================
// LINKED QUESTION GROUPS
// Multi-step review items with shared context (ECG interpretation, ABG, CXR, etc.)
// See docs/plans/2026-01-19-linked-question-groups-design.md
// =============================================================================

// QuestionGroup - Container for multi-step review with shared context
model QuestionGroup {
  id   String @id @default(cuid())
  slug String @unique // "ecg-inferior-stemi-001"
  type String // "ecg", "abg", "cxr"

  // Shared context displayed throughout all steps
  contextImageUrl String? // ECG/CXR image path
  contextText     String? @db.Text // "65yo male, crushing chest pain"

  // Steps stored as JSON array of QuestionGroupStep objects:
  // [{id, phase, phaseName, stepNumber, type, front?, back?, stem?, options?, context?}]
  steps Json

  // Metadata
  difficulty String   @default("medium") // 'easy' | 'medium' | 'hard'
  topics     String[] // ["STEMI", "inferior MI", "heart block"]
  rotation   String? // 'critical-care', etc.
  week       Int?

  // Summary shown at end
  diagnosisSummary String? @db.Text // "Inferior STEMI with 2:1 AV block"

  // Stats
  totalAttempts Int    @default(0)
  avgScore      Float? // Average % correct

  createdAt DateTime @default(now()) @db.Timestamptz(3)
  updatedAt DateTime @updatedAt @db.Timestamptz(3)

  @@index([type])
  @@index([rotation, week])
  @@index([difficulty])
}

// =============================================================================
// CARD VERSIONING (for audit trail reconstruction)
// Enables: "What exact content did User X see on Date Y?"
// =============================================================================

// CardVersion - Immutable snapshot of card content at time of creation
// NEVER delete these - they form the audit trail for safety investigations
// ContentVersion - Immutable snapshot of card/question content at time of creation
// NEVER delete these - they form the audit trail for safety investigations
model ContentVersion {
  id         String @id @default(cuid())
  targetType String // 'card' | 'question'
  targetId   String

  versionNumber Int // 1, 2, 3... per target

  // Content snapshot (immutable, stored as JSON)
  snapshot Json @db.JsonB // Full content snapshot (card fields or question fields)

  // Change tracking
  contentHash String // SHA-256 of content

  // Audit metadata
  createdBy String // 'seed', 'admin', userId
  createdAt DateTime @default(now()) @db.Timestamptz(3)

  // Relations
  learningEvents LearningEvent[]

  @@unique([targetType, targetId, versionNumber])
  @@index([targetType, targetId])
  @@index([createdAt])
  @@index([contentHash])
}

// ContentGap - Records sparse regions in the embedding space
// Detected during scheduling when a weak concept has too few nearby content items.
// Used to prioritize content creation.
model ContentGap {
  id                String    @id @default(cuid())
  conceptId         String?
  rotation          String
  gapType           String // 'format_gap' | 'pedagogical_gap' | 'true_gap'
  nearestSimilarity Float
  candidateCount    Int
  detectedAt        DateTime  @default(now()) @db.Timestamptz(3)
  resolvedAt        DateTime? @db.Timestamptz(3)

  concept Concept? @relation(fields: [conceptId], references: [id], onDelete: SetNull)

  @@index([rotation, gapType])
  @@index([detectedAt])
}

/**
 * CardConcept - Many-to-many: Card teaches multiple Concepts.
 *
 * Cards were the ONLY content type with no concept relation: questions have
 * QuestionConcept, facts have FactConcept, videos have VideoConcept, and cards
 * had nothing. Card.conceptId is NOT this and never was — it groups
 * jurisdiction variants of the same card, so writing concept ids into it would
 * silently make unrelated cards into AU/US twins of each other.
 *
 * `source` is here because most of these links will be DERIVED from the
 * manifold rather than authored, and the two must never be confused: a derived
 * link can be recomputed and discarded, an authored one is a human's claim and
 * has to survive a rebuild. `similarity` records what the geometry said at
 * derivation time, so a later drift is visible rather than silent.
 */
model CardConcept {
  id         String            @id @default(cuid())
  cardId     String
  conceptId  String
  isPrimary  Boolean           @default(false) // Is this the main concept taught?
  source     CardConceptSource @default(derived)
  /// Cosine at derivation time. Null for an authored link, which asserts the
  /// relationship regardless of where the vectors currently sit.
  similarity Float?
  createdAt  DateTime          @default(now()) @db.Timestamptz(3)

  card    Card    @relation(fields: [cardId], references: [id], onDelete: Cascade)
  concept Concept @relation(fields: [conceptId], references: [id], onDelete: Cascade)

  @@unique([cardId, conceptId])
  @@index([conceptId])
  @@index([conceptId, source])
}

enum CardConceptSource {
  authored
  derived
}

