/**
 * Timezone the course calendar is written in. The public distribution ships no
 * institution calendar, so this defaults to UTC; a deployment with a campus
 * calendar overrides it.
 */
export const COURSE_TIME_ZONE = 'UTC';

/**
 * `now`, collapsed to the calendar day in `timeZone` and re-stamped at UTC
 * midnight so it is directly comparable to a block start date.
 *
 * Implemented rather than stubbed: it is pure date arithmetic and discloses no
 * calendar, and callers that compare against block dates need it to behave.
 */
export function courseCalendarDay(now: Date, timeZone: string = COURSE_TIME_ZONE): Date {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (type: string): string => parts.find((part) => part.type === type)?.value ?? '01';
  return new Date(`${get('year')}-${get('month')}-${get('day')}T00:00:00.000Z`);
}

